<script lang="ts">
	import { gsap } from 'gsap';
	import { ScrollTrigger } from 'gsap/ScrollTrigger';
	gsap.registerPlugin(ScrollTrigger);

	$effect(() => {
		gsap.set('.dv', {
			transformOrigin: 'center center'
		});
		const timeline = gsap
			.timeline({
				scrollTrigger: {
					trigger: '#diamondsSVG',
					start: 'top 50%',
					toggleActions: 'play none none none'
				}
			})
			.addLabel('start');
		timeline
			.fromTo(
				'.dh',
				{
					opacity: 0.5,
					yPercent: 5
				},
				{
					opacity: 1,
					yPercent: -5,
					ease: 'ease',
					duration: 1,
					yoyo: true,
					yoyoEase: 'ease',
					repeat: -1,
					repeatDelay: 0.4,
					stagger: {
						each: 0.1,
						from: 'end',
						repeat: -1
					}
				}
			)
			.fromTo(
				'.dv',
				{
					opacity: 0
				},
				{
					opacity: 0.2,
					ease: 'ease.inOut',
					duration: 0.5
				},
				'start'
			);
	});
</script>

